import java.util.*;

class Solution {
    public int earliestCrossing(int[][] grid) {
        int n = grid.length;
        boolean[][] seen = new boolean[n][n];
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]); // {time, row, col}
        pq.add(new int[]{grid[0][0], 0, 0});
        seen[0][0] = true;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            if (cur[1] == n - 1 && cur[2] == n - 1) return cur[0];
            for (int[] d : dirs) {
                int x = cur[1] + d[0], y = cur[2] + d[1];
                if (x >= 0 && y >= 0 && x < n && y < n && !seen[x][y]) {
                    seen[x][y] = true;
                    pq.add(new int[]{Math.max(cur[0], grid[x][y]), x, y}); // route waits for its highest cell
                }
            }
        }
        return -1;
    }
}

