    def earliestCrossing(self, grid: List[List[int]]) -> int:
        n = len(grid); seen = {(0, 0)}; h = [(grid[0][0], 0, 0)]
        while h:
            t, i, j = heappop(h)
            if (i, j) == (n-1, n-1): return t
            for x, y in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
                if 0 <= x < n and 0 <= y < n and (x, y) not in seen:
                    seen.add((x, y)); heappush(h, (max(t, grid[x][y]), x, y))

