function earliestCrossing(grid) {
  const n = grid.length;
  const ok = t => { if (grid[0][0] > t) return false; const s = grid.map(r => r.map(() => false)), st = [[0, 0]]; s[0][0] = true;
    while (st.length) { const [i, j] = st.pop(); if (i === n-1 && j === n-1) return true;
      for (const [x, y] of [[i+1,j],[i-1,j],[i,j+1],[i,j-1]]) if (x >= 0 && x < n && y >= 0 && y < n && !s[x][y] && grid[x][y] <= t) { s[x][y] = true; st.push([x, y]); } }
    return false; };
  let lo = 0, hi = n * n - 1;
  while (lo < hi) { const m = (lo + hi) >> 1; if (ok(m)) hi = m; else lo = m + 1; }
  return lo;
}
